-- CAB-0010: scoped editorial import. Deploy portrait/logo assets before applying.

begin;

do $$ begin
 if not exists(select 1 from public.entities where slug='dap' and type='party') then raise exception 'CAB-0010: missing or wrong parent'; end if;
 if not exists(select 1 from public.entities where slug='umno' and type='party') then raise exception 'CAB-0010: missing or wrong parent'; end if;
 if exists(select 1 from public.entities where slug in ('hannah-yeoh','johari-abdul-ghani') and (type <> 'politician' or owner_id is not null)) then raise exception 'CAB-0010: ownership or type conflict'; end if;
 if exists(select 1 from public.entities where type='politician' and lower(constituency) in ('segambut','titiwangsa') and slug not in ('hannah-yeoh','johari-abdul-ghani')) then raise exception 'CAB-0010: constituency identity conflict'; end if;
 if exists(select 1 from public.milestones m join public.entities e on e.id=m.entity_id where m.import_key like 'CAB-0010:%' and (m.source_type <> 'editorial' or e.slug not in ('hannah-yeoh','johari-abdul-ghani') or m.import_key not like 'CAB-0010:' || e.slug || ':%')) then raise exception 'CAB-0010: milestone identity conflict'; end if;
end $$;

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician', parent.id,'hannah-yeoh','Hannah Yeoh','government','Minister in the Prime Minister’s Department (Federal Territories)','Segambut','Kuala Lumpur','Hannah Yeoh is Minister in the Prime Minister’s Department (Federal Territories). She represents Segambut, Kuala Lumpur, in the Dewan Rakyat. She is a member of DAP.','https://www.jwp.gov.my/','/portraits/hannah-yeoh.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P117.png','Parliament of Malaysia','2026-11-09','[{"label": "Prime Minister’s Office · Cabinet", "url": "https://www.pmo.gov.my/en/cabinet/"}, {"label": "Parliament · Segambut", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4156"}, {"label": "DAP · current leadership", "url": "https://dapmalaysia.org/en/our-leaders/"}]'::jsonb from public.entities parent where parent.slug='dap' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician', parent.id,'johari-abdul-ghani','Johari Abdul Ghani','government','Minister of Investment, Trade and Industry','Titiwangsa','Kuala Lumpur','Johari Abdul Ghani is Minister of Investment, Trade and Industry. He represents Titiwangsa, Kuala Lumpur, in the Dewan Rakyat. He is a member of UMNO.','https://www.miti.gov.my/','/portraits/johari-abdul-ghani.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P119.png','Parliament of Malaysia','2026-11-09','[{"label": "Prime Minister’s Office · Cabinet", "url": "https://www.pmo.gov.my/en/cabinet/"}, {"label": "Parliament · Titiwangsa", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4158"}, {"label": "UMNO · 2023–2026 supreme council", "url": "https://umno-online.my/wp-content/uploads/2026/01/Senarai-MKT-2023-2026-update-Januari-2026-jan-2026-final.pdf"}]'::jsonb from public.entities parent where parent.slug='umno' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

do $$ begin if (select count(*) from public.entities where slug in ('hannah-yeoh','johari-abdul-ghani') and type='politician' and owner_id is null) <> 2 then raise exception 'CAB-0010: concurrent ownership or identity change'; end if; end $$;

insert into public.milestones (entity_id,import_key,title,category,status,progress,target_date,promise_date,promise_url,evidence_date,evidence_url,description,progress_note,progress_checked_at,source_type,is_sample) select e.id,'CAB-0010:hannah-yeoh:resurface-51-pa-ppr','Resurface roads in all 51 DBKL PA and PPR housing areas','Infrastructure','in_progress',14,null,'2026-03-16','https://jwp.gov.my/storage/media/KENYATAAN-MEDIA-BELANJA-UNTUK-RAKYAT--BUAT-PERTAMA-KALI-KERJA-PENURAPAN-JALAN-DILAKSANAKAN-SECARA-MENYELURUH-DI-SEMUA-51-PA-DAN-PPR-SELIAAN-DBKL-DI-KUALA-LUM.pdf','2026-03-16','https://jwp.gov.my/storage/media/KENYATAAN-MEDIA-BELANJA-UNTUK-RAKYAT--BUAT-PERTAMA-KALI-KERJA-PENURAPAN-JALAN-DILAKSANAKAN-SECARA-MENYELURUH-DI-SEMUA-51-PA-DAN-PPR-SELIAAN-DBKL-DI-KUALA-LUM.pdf','Hannah’s signed statement commits to comprehensive road resurfacing in all 51 public-housing areas under DBKL.','The statement’s first-quarter snapshot reports seven completed locations and two under way. The bar is 7 ÷ 51 × 100 = 13.73%, rounded to 14%. It measures completed locations, not road length or expenditure. This is the verified 16 March snapshot; later completion was not established.','2026-11-09','editorial',false from public.entities e where e.slug='hannah-yeoh' on conflict (import_key) do update set title=excluded.title,category=excluded.category,status=excluded.status,progress=excluded.progress,target_date=excluded.target_date,promise_date=excluded.promise_date,promise_url=excluded.promise_url,evidence_date=excluded.evidence_date,evidence_url=excluded.evidence_url,description=excluded.description,progress_note=excluded.progress_note,progress_checked_at=excluded.progress_checked_at,source_type=excluded.source_type,is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial' and ROW(public.milestones.title,public.milestones.category,public.milestones.status,public.milestones.progress,public.milestones.target_date,public.milestones.promise_date,public.milestones.promise_url,public.milestones.evidence_date,public.milestones.evidence_url,public.milestones.description,public.milestones.progress_note,public.milestones.progress_checked_at,public.milestones.source_type,public.milestones.is_sample) IS DISTINCT FROM ROW(excluded.title,excluded.category,excluded.status,excluded.progress,excluded.target_date,excluded.promise_date,excluded.promise_url,excluded.evidence_date,excluded.evidence_url,excluded.description,excluded.progress_note,excluded.progress_checked_at,excluded.source_type,excluded.is_sample);

insert into public.milestones (entity_id,import_key,title,category,status,progress,target_date,promise_date,promise_url,evidence_date,evidence_url,description,progress_note,progress_checked_at,source_type,is_sample) select e.id,'CAB-0010:hannah-yeoh:resurface-59km-main-roads','Resurface 59 kilometres of Kuala Lumpur’s protocol and main roads','Infrastructure','in_progress',null,null,'2026-08-19','https://bernama.com/en/general/news.php?id=2596675','2026-08-20','https://bernama.com/en/general/news.php?id=2596675','Hannah outlined DBKL’s staged Eight-Road Resurfacing Programme covering 59 kilometres of protocol and main roads.','The 20 August report records her inspection of active resurfacing works. It describes two phases and phase-specific schedules, not a verified completed distance for the whole programme. Overall completion and a single final deadline remain blank.','2026-11-09','editorial',false from public.entities e where e.slug='hannah-yeoh' on conflict (import_key) do update set title=excluded.title,category=excluded.category,status=excluded.status,progress=excluded.progress,target_date=excluded.target_date,promise_date=excluded.promise_date,promise_url=excluded.promise_url,evidence_date=excluded.evidence_date,evidence_url=excluded.evidence_url,description=excluded.description,progress_note=excluded.progress_note,progress_checked_at=excluded.progress_checked_at,source_type=excluded.source_type,is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial' and ROW(public.milestones.title,public.milestones.category,public.milestones.status,public.milestones.progress,public.milestones.target_date,public.milestones.promise_date,public.milestones.promise_url,public.milestones.evidence_date,public.milestones.evidence_url,public.milestones.description,public.milestones.progress_note,public.milestones.progress_checked_at,public.milestones.source_type,public.milestones.is_sample) IS DISTINCT FROM ROW(excluded.title,excluded.category,excluded.status,excluded.progress,excluded.target_date,excluded.promise_date,excluded.promise_url,excluded.evidence_date,excluded.evidence_url,excluded.description,excluded.progress_note,excluded.progress_checked_at,excluded.source_type,excluded.is_sample);

insert into public.milestones (entity_id,import_key,title,category,status,progress,target_date,promise_date,promise_url,evidence_date,evidence_url,description,progress_note,progress_checked_at,source_type,is_sample) select e.id,'CAB-0010:johari-abdul-ghani:nif-jobs-supply-chain','Link NIF investment incentives to high-value jobs and local suppliers','Economy','in_progress',null,null,'2026-10-21','https://www.bernama.com/en/news.php?id=2623543','2026-10-21','https://www.bernama.com/en/news.php?id=2623543','In Parliament, Johari said investment-incentive applicants must demonstrate local supply-chain links and high-income, high-value job creation under NIF.','His update describes the framework operating since March and its continuing conditions for applicants. This records his stated implementation commitment, not personal credit for the original launch. Actual job and supplier outcomes against those conditions were not quantified; no completion score is assigned.','2026-11-09','editorial',false from public.entities e where e.slug='johari-abdul-ghani' on conflict (import_key) do update set title=excluded.title,category=excluded.category,status=excluded.status,progress=excluded.progress,target_date=excluded.target_date,promise_date=excluded.promise_date,promise_url=excluded.promise_url,evidence_date=excluded.evidence_date,evidence_url=excluded.evidence_url,description=excluded.description,progress_note=excluded.progress_note,progress_checked_at=excluded.progress_checked_at,source_type=excluded.source_type,is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial' and ROW(public.milestones.title,public.milestones.category,public.milestones.status,public.milestones.progress,public.milestones.target_date,public.milestones.promise_date,public.milestones.promise_url,public.milestones.evidence_date,public.milestones.evidence_url,public.milestones.description,public.milestones.progress_note,public.milestones.progress_checked_at,public.milestones.source_type,public.milestones.is_sample) IS DISTINCT FROM ROW(excluded.title,excluded.category,excluded.status,excluded.progress,excluded.target_date,excluded.promise_date,excluded.promise_url,excluded.evidence_date,excluded.evidence_url,excluded.description,excluded.progress_note,excluded.progress_checked_at,excluded.source_type,excluded.is_sample);

